theorem dist_borrow_eq4 (s1 : St) (who : Nat) (s' : St)
    (h : distributeBorrowerComp s1 who = some s') :
    s' = { s1 with accts := s1.accts.modify who fun a => { a with borrowerIndex := s1.borrowState.index, accrued := a.accrued + creditFor a.borrow (accrualStart a.borrowerIndex s1.borrowState.index) s1.borrowState.index } }

theorem dist_supply_eq4 (s1 : St) (who : Nat) (s' : St)
    (h : distributeSupplierComp s1 who = some s') :
    s' = { s1 with accts := s1.accts.modify who fun a => { a with supplierIndex := s1.supplyState.index, accrued := a.accrued + creditFor a.supply (accrualStart a.supplierIndex s1.supplyState.index) s1.supplyState.index } }
